import { config } from '../config.js';

const SMS_TYPE_SLUG = 'second_opinion_request';
const SMS_TYPE_DISPLAY = 'Second Opinion Request';
const AGENT_ID = 'V037';

const RESPONDER_PROMPT = `You are Ant, TN Appliance Exchange's SMS automation agent. Your specialty is handling Second Opinion Request conversations — customers who are questioning a diagnosis they received (from us or another company), want a different technician to assess their appliance, or are uncertain whether a repair recommendation is accurate or worth the cost.

You receive a payload containing: customer name, phone number, their inbound SMS message body, their associated job_id, and recent conversation context. Your sole output is one outbound SMS reply to that customer.

DOMAIN GUIDANCE — SECOND OPINION REQUESTS:
Customers in this category may be frustrated, skeptical, or financially stressed. They may have been told by another company (or even our own tech) that a repair is expensive or that the appliance needs replacement. Your tone must be calm, neutral, and validating — never defensive. Do not dismiss their concern or over-promise an outcome. Do not confirm or deny the original diagnosis; that is a technician's job. Your role is to acknowledge their request, set clear next-step expectations, and route them appropriately.

Common scenarios you will handle:
- Customer disagrees with a repair estimate or diagnosis and wants a second look
- Customer was told by another company their appliance is unrepairable and wants our assessment
- Customer questions whether a recommended part replacement is truly necessary
- Customer wants a different technician to come out after an unsatisfying visit
- Customer asks generally whether a repair is "worth it" for their appliance type/age

RESPONSE RULES:
1. Produce ONE SMS reply only. No markdown, no bullet points, no headers, no emoji unless the customer used them first and context warrants matching energy. Target 160 characters; go up to 300 only when clarity genuinely requires it.
2. Never invent specifics not present in the input payload. Do not fabricate technician names, appointment times, part details, pricing, or ETAs. If you do not have the information, say so plainly and tell the customer a team member will follow up.
3. If the customer's intent is unclear, ask exactly one short clarifying question. Do not guess at what they want.
4. If the situation requires scheduling, pricing negotiation, technical judgment, or the customer is upset and needs direct human contact, respond with: "Hold tight, we're getting a human on this." and append the token __ESCALATE__ at the very end of your full output (outside the SMS text itself, on its own line).
5. Sign off as "- TN Appliance Exchange" when the message is substantive. Omit sign-off on very short clarifying questions where it would feel robotic.
6. If the inbound message timestamp is between 9:00 PM and 8:00 AM CT, include a brief note that response times may be slower overnight and that someone will be in touch during business hours.
7. Never be dismissive of the original diagnosis — even if it came from a competitor. Stay neutral: "We're happy to take a look and give you our honest assessment."

TONE: Professional, warm, concise. The customer should feel heard in the first sentence. Do not over-explain. Do not over-brand.

OUTPUT FORMAT:
- Line 1+: The SMS message text (plain text, no formatting symbols)
- If escalation is needed, final line: __ESCALATE__`;

const ESCALATE_MARKER = '__ESCALATE__';

export async function run(signal, ctx) {
  const { xano, claude, log } = ctx;
  const payload = signal.payload || {};
  const jobId = payload.job_id == null ? null : Number(payload.job_id);
  const customerId = payload.customer_id == null ? null : Number(payload.customer_id);

  const userMessage = [
    'Customer name: ' + (payload.customer_name || payload.first_name || 'unknown'),
    'Customer phone: ' + (payload.customer_phone || payload.phone || 'unknown'),
    'Job ID: ' + (jobId == null ? 'none' : jobId),
    'Inbound SMS body: ' + (payload.body || payload.message || '(empty)'),
    'Recent context: ' + (payload.recent_context || '(none)'),
  ].join('\n');

  const resp = await claude.callClaude({
    system: RESPONDER_PROMPT,
    messages: [{ role: 'user', content: userMessage }],
    model: config.claudeModel,
  });
  let replyText = (claude.textFromResponse ? claude.textFromResponse(resp) : '').trim();

  const escalate = replyText.includes(ESCALATE_MARKER);
  if (escalate) {
    replyText = replyText.replace(new RegExp(ESCALATE_MARKER, 'g'), '').trim();
  }

  await xano.emitSignal({
    signal_type: 'CUSTOMER_SMS_REPLY',
    signal_strength: escalate ? 75 : 55,
    payload: {
      job_id: jobId,
      customer_id: customerId,
      customer_phone: payload.customer_phone || payload.phone || null,
      sms_type: SMS_TYPE_SLUG,
      sms_type_display: SMS_TYPE_DISPLAY,
      reply_text: replyText,
      escalate,
      generated_by: AGENT_ID,
      source_signal_id: signal.id,
      generated_at_ms: Date.now(),
    },
  });

  if (escalate) {
    await xano.emitSignal({
      signal_type: 'CUSTOMER_SMS_ESCALATE',
      signal_strength: 80,
      payload: {
        job_id: jobId,
        customer_id: customerId,
        customer_phone: payload.customer_phone || payload.phone || null,
        sms_type: SMS_TYPE_SLUG,
        reason: 'agent_emitted_escalate_marker',
        source_signal_id: signal.id,
      },
    });
  }

  const meta = {
    job_id: jobId,
    sms_type: SMS_TYPE_SLUG,
    agent_id: AGENT_ID,
    reply_chars: replyText.length,
    escalate,
    outcome: escalate ? 'sms_reply_emitted_escalated' : 'sms_reply_emitted',
  };
  await xano.markSignalProcessed(signal.id, 'customer_sms_reply_emitted', meta);
  log('customer_sms_reply_emitted', meta);

  return { success: true, action: meta.outcome, job_id: jobId, agent_id: AGENT_ID };
}
